const telegramResponse = $input.first().json;
const updates = Array.isArray(telegramResponse.result) ? telegramResponse.result : [];
const configuredUserId = Number($env.SAGE_TELEGRAM_ALLOWED_USER_ID);
const configuredChatId = Number($env.SAGE_TELEGRAM_CHAT_ID);
const configuredTopicIds = new Set([
  Number($env.SAGE_TELEGRAM_MAIN_TOPIC_ID),
  Number($env.SAGE_TELEGRAM_REPORTS_TOPIC_ID),
  Number($env.SAGE_TELEGRAM_NOTIFICATIONS_TOPIC_ID),
]);
const latestUpdateId = updates.reduce((latestId, update) => Math.max(latestId, Number(update.update_id) || 0), 0);
const messages = updates.flatMap((update) => {
  const message = update.message;
  if (!message || typeof message.text !== 'string') return [];
  if (message.from?.id !== configuredUserId || message.chat?.id !== configuredChatId) return [];
  if (!configuredTopicIds.has(message.message_thread_id)) return [];
  return [{
    json: {
      chatId: message.chat.id,
      messageId: message.message_id,
      messageThreadId: message.message_thread_id,
      senderId: message.from.id,
      text: message.text,
    },
  }];
});
const workflowState = $getWorkflowStaticData('global');
if (latestUpdateId > 0) {
  if (messages.length === 0) {
    workflowState.nextUpdateOffset = latestUpdateId + 1;
    delete workflowState.pendingUpdateOffset;
  } else {
    workflowState.pendingUpdateOffset = latestUpdateId + 1;
  }
}
return messages;

const workflowState = $getWorkflowStaticData('global');
if (typeof workflowState.pendingUpdateOffset === 'number') {
  workflowState.nextUpdateOffset = workflowState.pendingUpdateOffset;
  delete workflowState.pendingUpdateOffset;
}
return $input.all();
